CREATE TABLE contracts(id BINARY(16) PRIMARY KEY,contract_number VARCHAR(255) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL,created_by BINARY(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL,terminated_at TIMESTAMP(6),termination_reason VARCHAR(1000),revision BIGINT NOT NULL);
CREATE TABLE contract_parties(id BINARY(16) PRIMARY KEY,contract_id BINARY(16) NOT NULL,party_id BINARY(16) NOT NULL,party_type VARCHAR(30) NOT NULL,role VARCHAR(100) NOT NULL,FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE);
CREATE TABLE contract_versions(id BINARY(16) PRIMARY KEY,contract_id BINARY(16) NOT NULL,version_number INT NOT NULL,effective_date DATE NOT NULL,expiration_date DATE,territories_json TEXT NOT NULL,game_rights_json TEXT NOT NULL,revenue_agreement_json TEXT NOT NULL,attachment_key VARCHAR(512),status VARCHAR(30) NOT NULL,approved_by BINARY(16),UNIQUE(contract_id,version_number),FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE);